server.registerTool("wechat_message_list",{
  title:"List visible messages in one WeChat conversation",
  description:"Select one EXACT WeChat chat (default refuses marking unread messages read), then return only message rows currently exposed in the native accessibility Messages viewport, in top-to-bottom order. No full history, stable message IDs, or guaranteed sender identity/direction. Empty visible rows never prove an empty chat.",
  inputSchema:{target:z.string().trim().min(1).max(256),
    limit:z.number().int().min(1).max(50).optional(),
    allow_mark_read:z.boolean().optional()},
  annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:true},
},async({target,limit=10,allow_mark_read=false})=>{
  try {
    const x=await postJson(semanticUrl,"/message-list",
      {target,limit,allow_mark_read},"WECHAT_MESSAGE_LIST_FAILED",16000);
    if(x?.provider!=="wechat"||x?.conversation!==target||
       x?.complete!==false||!Array.isArray(x?.messages)||
       !["ACHIEVED","INCOMPLETE"].includes(x.state)||
       x.messages.length>limit ||
       x.scope!=="bounded_visible_messages_only")
      throw codedError("WECHAT_MESSAGE_LIST_PROOF_INVALID");
    return result({ok:true,state:x.state,provider:"wechat",...x});
  } catch(error) {return failure(error,"WECHAT_MESSAGE_LIST_FAILED");}
});

